/** One claim of turn `turn`, number `i` (1-based): the fold (ARG0) `rel` (said / showed / derived …) the unit's text VERBATIM (ARG1). Empty text is no claim (null). */
export function claimAt(turn, i, rel, text, basis = null) {
  const t = String(text ?? "");
  if (!t.trim()) return null;
  return gfpClaim({ ground: `${turnAddress(turn)}/c${i}`, rel, roles: { ARG0: "fold", ARG1: t }, id: `t${Number(turn) || 0}c${i}`, basis });
